dispatch = Dispatcher()      # sysone's generic functions: `@dispatch` defines one, `f.register(fn)` adds a method from anywhere

def methods(f) -> list:
    "The signatures a generic function has methods for, as tuples of class names, in the order they were added"
    name = lambda t: t.__name__ if isinstance(t, type) else str(t)
    return [tuple(name(t) for t in m.signature.types) for m in f.methods]

