def render_criterion(value) -> str:
    "A criterion value as text: strings pass through, anything structured becomes compact JSON"
    if isinstance(value, str): return value
    return json.dumps(value, ensure_ascii=False, separators=(", ", ": "), default=str)

_NOUL_DEFAULTS = {"false": "no, the statement does not hold", "true": "yes, the statement holds"}

@patch(as_prop=True)
def qtype(self:Question) -> int: "The type's integer id"; return QTYPES[self.type]

@patch(as_prop=True)
def keys(self:Choice) -> list: "A choice's answer keys: its labels"; return list(self.criteria)
@patch(as_prop=True)
def keys(self:Score) -> list: "A score's answer keys: its levels' indices, as strings"; return [str(i) for i in range(len(self.criteria))]
@patch(as_prop=True)
def keys(self:Noul) -> list: "A noul's answer keys: false, then true"; return list(NOUL_KEYS)

@patch(as_prop=True)
def k(self:Question) -> int: "Number of options"; return len(self.keys)

@patch(as_prop=True)
def options(self:Choice) -> list:
    "A choice's option texts, as Laya renders them: `label: description`, or the label alone"
    return [str(k) if v is None or v == "" else f"{k}: {render_criterion(v)}" for k, v in self.criteria.items()]

@patch(as_prop=True)
def options(self:Score) -> list:
    "A score's option texts: `level i: description`"
    return [f"level {i}: {render_criterion(c)}" for i, c in enumerate(self.criteria)]

@patch(as_prop=True)
def options(self:Noul) -> list:
    "A noul's option texts, false then true, with Laya's default descriptions when none is given"
    crit, labels = self.criteria or {}, self.labels or {"false": "false", "true": "true"}
    return [f"{labels[key].strip()}: " + (render_criterion(crit[key]) if crit.get(key) not in (None, "") else _NOUL_DEFAULTS[key])
            for key in NOUL_KEYS]

