def _two_point(score, n):
    "A distribution over n levels whose expected level is `score`"
    s = min(max(float(score), 0.0), n - 1.0)
    lo = int(math.floor(s)); p = [0.0] * n
    if lo >= n - 1: p[n - 1] = 1.0
    else: p[lo], p[lo + 1] = 1.0 - (s - lo), s - lo
    return p

def _noul_key(v) -> str:
    "A truth value's key: 'true' or 'false' for yes/no, booleans, 1/0"
    s = str(v).strip().lower()
    return {"yes": "true", "no": "false", "1": "true", "0": "false", "1.0": "true", "0.0": "false"}.get(s, s)

def _str_key(k) -> str:
    "A key as text, integral floats without their '.0'"
    return str(int(k)) if isinstance(k, float) and k.is_integer() else str(k)

@patch
def _label_index(self:Question, label) -> int:
    "Index of a gold label among the question's keys, or -1"
    if label is None: return -1
    keys = [_str_key(k) for k in self.keys]
    return keys.index(_str_key(label)) if _str_key(label) in keys else -1

@patch
def _label_index(self:Noul, label) -> int:
    "Index of a truth value among false and true, or -1"
    if label is None: return -1
    s = _noul_key(label)
    return NOUL_KEYS.index(s) if s in NOUL_KEYS else -1

@patch
def _bare_gold(self:Question, v) -> dict: "A bare gold value: a label"; return {"label": v}

@patch
def _bare_gold(self:Score, v) -> dict:
    "A bare gold value: an expected level when fractional, else a label"
    return {"score": v} if isinstance(v, float) and not v.is_integer() else {"label": v}

@patch
def _bare_gold(self:Noul, v) -> dict:
    "A bare gold value: p(true) when fractional, else a label"
    return {"noul": v} if isinstance(v, float) and not v.is_integer() else {"label": v}

@patch
def _probs_target(self:Question, probs:dict):
    "A gold distribution given as `{key: probability}`, in key order"
    pk = {_str_key(k): v for k, v in probs.items()}
    return [float(pk.get(_str_key(k), 0.0)) for k in self.keys]

@patch
def _probs_target(self:Noul, probs:dict):
    "A gold distribution over false and true, either side giving the other"
    pn = {_noul_key(k): v for k, v in probs.items()}
    pt, pf = pn.get("true"), pn.get("false")
    if pt is None and pf is None: return None
    pt = 1.0 - pf if pt is None else pt
    pf = 1.0 - pt if pf is None else pf
    return [float(pf), float(pt)]

@patch
def _field_target(self:Question, gold:dict): "The distribution the kind's own field of the gold gives (a choice has none)"; return None

@patch
def _field_target(self:Score, gold:dict):
    "A score's expected level, as the distribution over two neighbouring levels that has it"
    return _two_point(gold["score"], self.k) if gold.get("score") is not None else None

@patch
def _field_target(self:Noul, gold:dict):
    "A noul's p(true), as the distribution over false and true"
    return [1.0 - float(gold["noul"]), float(gold["noul"])] if gold.get("noul") is not None else None

@patch
def target(self:Question, gold) -> tuple:
    "The gold distribution over options (key order) and the gold label's index; `(None, -1)` without gold"
    if gold is None: return None, -1
    if isinstance(gold, (list, tuple)) and len(gold) == self.k and all(isinstance(v, (int, float)) for v in gold):
        t, label = [float(v) for v in gold], -1
    else:
        if not isinstance(gold, dict): gold = self._bare_gold(gold)      # a label, or an expected score or p(true) when fractional
        label, probs, t = self._label_index(gold.get("label")), gold.get("probabilities"), None
        if isinstance(probs, dict) and probs:
            t = self._probs_target(probs)
            if t is not None and sum(t) <= 0: t = None     # the distribution names none of the options
        if t is None: t = self._field_target(gold)         # a noul's p(true), a score's expected level
        if t is None and label >= 0: t = [float(i == label) for i in range(self.k)]
        if t is None: return None, -1
    s = sum(t)
    t = [v / s for v in t] if s > 0 else [1.0 / len(t)] * len(t)
    return t, (label if label >= 0 else int(np.argmax(t)))

