ADAPTERS = {"NeoMMEProcessor": "sysone.multimodal", "NeoMMEConfig": "sysone.multimodal",
            "Idefics3Processor": "sysone.modernvbert", "ModernVBertConfig": "sysone.modernvbert"}   # a class's name: the sysone module that adapts it

def load_adapter(obj) -> bool:
    "Import the sysone module that adapts `obj`'s class or one of its bases, if it isn't imported yet: whether one was"
    for cls in type(obj).__mro__:
        mod = ADAPTERS.get(cls.__name__)
        if mod is not None and mod not in sys.modules:
            importlib.import_module(mod)
            return True
    return False
